package cn.local.rainreminder;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import android.widget.*;import android.view.View;import org.json.*;import java.io.*;
public class SchoolImportActivity extends Activity {
 static final String PORTAL="https://jyjx.hzau.edu.cn/personal-center";
 WebView web;TextView hint,progressTitle;Button read;ProgressBar pageProgress;LinearLayout actionBar,progressBox;
 String script,anchor,mobileScript,examAuto;boolean reading,examsMode,autoEnabled=true,completed,examOpened,portalRedirected;int generation,examPage=1;long deadline;JSONArray examRows=new JSONArray();
 final Handler handler=new Handler(Looper.getMainLooper());final Runnable tick=()->advance(generation);
 String asset(String name)throws IOException{try(InputStream in=getAssets().open(name)){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);return bytes.toString("UTF-8");}}
 public void onCreate(Bundle state){super.onCreate(state);examsMode=getIntent().getBooleanExtra("exams",false);try{script=asset(examsMode?"exam-reader.js":"school-reader.js");examAuto=asset("school-exam-auto.js");}catch(Exception e){Ui.error(this,e);finish();return;}
  LinearLayout content=Ui.screen(this,examsMode?"查询学校考试":"学校导入课表");Ui.topAction(this,content,"重试",this::restart);LinearLayout page=Ui.page(content);page.removeView((View)content.getParent());LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,20),Ui.dp(this,4),Ui.dp(this,20),Ui.dp(this,10));page.addView(box);TextView steps=Ui.text(this,"登录学校  →  自动读取  →  核对保存",12);steps.setTextColor(Ui.GREEN);box.addView(steps);hint=Ui.hint(this,"正在连接学校官网…");hint.setTextSize(12);hint.setMaxLines(3);box.addView(hint);pageProgress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pageProgress.setIndeterminate(true);page.addView(pageProgress,new LinearLayout.LayoutParams(-1,Ui.dp(this,2)));
  android.widget.FrameLayout frame=new android.widget.FrameLayout(this);page.addView(frame,new LinearLayout.LayoutParams(-1,0,1));web=new WebView(this);Scanner.configure(web);web.getSettings().setSaveFormData(false);web.getSettings().setBuiltInZoomControls(true);web.getSettings().setDisplayZoomControls(false);web.getSettings().setUseWideViewPort(true);web.getSettings().setLoadWithOverviewMode(true);web.getSettings().setSupportMultipleWindows(true);web.getSettings().setJavaScriptCanOpenWindowsAutomatically(true);web.setWebViewClient(new ReaderClient());web.setWebChromeClient(new WebChromeClient(){public boolean onCreateWindow(WebView parent,boolean dialog,boolean gesture,Message message){if(!gesture&&!autoEnabled)return false;WebView child=new WebView(SchoolImportActivity.this);Scanner.configure(child);child.setWebViewClient(new WebViewClient(){boolean sent;void forward(WebView v,String url){if(sent||!allowed(url))return;sent=true;web.loadUrl(url);v.post(v::destroy);}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){forward(v,r.getUrl().toString());return true;}public void onPageStarted(WebView v,String url,android.graphics.Bitmap icon){forward(v,url);}});((WebView.WebViewTransport)message.obj).setWebView(child);message.sendToTarget();return true;}});frame.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));
  progressBox=Ui.column(this);progressBox.setGravity(android.view.Gravity.CENTER);progressBox.setPadding(Ui.dp(this,28),Ui.dp(this,24),Ui.dp(this,28),Ui.dp(this,24));progressBox.setBackgroundColor(Ui.PAGE);frame.addView(progressBox,new android.widget.FrameLayout.LayoutParams(-1,-1));progressBox.addView(new ProgressBar(this));progressTitle=Ui.text(this,"正在连接学校",21);progressBox.addView(progressTitle);TextView detail=Ui.hint(this,"登录后自动查找并读取，无需自己寻找入口");detail.setGravity(android.view.Gravity.CENTER);progressBox.addView(detail);
  actionBar=Ui.column(this);actionBar.setPadding(Ui.dp(this,20),0,Ui.dp(this,20),Ui.dp(this,8));actionBar.setBackgroundColor(android.graphics.Color.WHITE);page.addView(actionBar);read=Ui.button(this,actionBar,"取消读取",()->{if(autoEnabled)stop("已暂停自动读取，可点重试重新开始。");else restart();});web.loadUrl(PORTAL);
 }
 class ReaderClient extends WebViewClient {
  public void onPageStarted(WebView w,String url,android.graphics.Bitmap icon){generation++;handler.removeCallbacks(tick);pageProgress.setVisibility(View.VISIBLE);if(isSchoolLogin(url)){reading=false;deadline=0;showLogin();}else if(autoEnabled)showProgress("正在进入学校页面");}
  public void onPageFinished(WebView w,String url){adaptLogin(w,url);pageProgress.setVisibility(View.GONE);if(!autoEnabled||completed)return;if(isSchoolLogin(url)){reading=false;deadline=0;showLogin();return;}queue(250);}
  public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame()&&autoEnabled)stop("学校页面加载失败，请检查网络后重试。");}
  public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){if(!r.isForMainFrame())return false;if(allowed(r.getUrl().toString()))return false;if(autoEnabled)stop("学校跳转到暂不支持的页面，请在网页中核对后重试。");return true;}
 }
 void showLogin(){progressBox.setVisibility(View.GONE);actionBar.setVisibility(View.GONE);web.setVisibility(View.VISIBLE);hint.setText("请在学校官网登录；登录成功后会自动查询并读取。");}
 void showProgress(String message){reading=true;progressBox.setVisibility(View.VISIBLE);progressTitle.setText(message);actionBar.setVisibility(View.VISIBLE);read.setText("取消读取");hint.setText(message+"，请稍候…");}
 void queue(long delay){handler.removeCallbacks(tick);if(autoEnabled&&!completed)handler.postDelayed(tick,delay);}
 boolean current(int token){return token==generation&&autoEnabled&&!completed&&!isFinishing()&&!isDestroyed();}
 static boolean portal(String url){try{android.net.Uri u=android.net.Uri.parse(url);return "https".equals(u.getScheme())&&"jyjx.hzau.edu.cn".equals(u.getHost());}catch(Exception e){return false;}}
 static boolean examPage(String url){try{android.net.Uri u=android.net.Uri.parse(url);return "byjxyt.hzau.edu.cn".equals(u.getHost())&&u.getPath()!=null&&u.getPath().startsWith("/kwgl/kscx_cxXsksxxIndex.html");}catch(Exception e){return false;}}
 JSONObject result(String raw)throws Exception{return new JSONObject(String.valueOf(new JSONTokener(raw).nextValue()));}
 void advance(int token){if(!current(token))return;String url=web.getUrl();if(isSchoolLogin(url)){reading=false;deadline=0;showLogin();return;}if(deadline==0)deadline=System.currentTimeMillis()+60000;if(System.currentTimeMillis()>deadline){stop("自动读取超时，学校页面可能仍在加载。可重试，不会改动已有课表。");return;}
  if(examsMode&&examPage(url)){showProgress("正在查询考试 · 第 "+examPage+" 页");web.evaluateJavascript(examAuto,raw->{if(!current(token))return;try{JSONObject state=result(raw);if("ready".equals(state.optString("phase")))readExams(token);else queue(500);}catch(Exception e){stop("考试查询未能完成，请重试。");}});return;}
  if(!portal(url)){showProgress("正在等待学校登录跳转");queue(500);return;}
  if(!"/personal-center".equals(android.net.Uri.parse(url).getPath())&&!portalRedirected){portalRedirected=true;showProgress("正在自动进入个人中心");web.loadUrl(PORTAL);return;}
  if(examsMode){showProgress("正在自动打开考试信息");if(examOpened){queue(500);return;}web.evaluateJavascript("(function(){var entry=document.querySelector('li[title=\"考试信息\"]');if(!entry)return false;entry.click();return true;})();",raw->{if(!current(token))return;if("true".equals(raw))examOpened=true;queue(500);});return;}
  showProgress("正在自动读取学期课表");web.evaluateJavascript(script,raw->{if(!current(token))return;try{JSONObject data=result(raw);if(data.has("error")){queue(500);return;}if(data.has("week")){String candidate=data.optString("week");try{SchoolSchedule.firstMonday(candidate);}catch(IllegalArgumentException pending){showProgress("正在等待学校周次和日期加载");queue(500);return;}anchor=candidate;switchTab("学期课表");queue(500);}else if(anchor==null){switchTab("周课表");queue(500);}else{JSONArray draft=SchoolSchedule.events(this,data,anchor);review(new Intent(this,ImportActivity.class).putExtra("schoolDraft",draft.toString()));}}catch(Exception e){stop(e.getMessage()==null?"课表格式暂不支持，请重试。":e.getMessage());}});
 }
 void readExams(int token){web.evaluateJavascript(script,raw->{if(!current(token))return;try{JSONObject data=result(raw);if(data.has("error")){queue(500);return;}JSONArray rows=data.getJSONArray("exams");int pages=data.optInt("pages",1);if(rows.length()>0&&data.optInt("page",examPage)!=examPage){stop("考试分页未能核对，未保存结果，请重试。");return;}if(pages>20||examPage>20){stop("考试结果超过20页，已停止读取，请在网页缩小查询范围后重试。");return;}for(int n=0;n<rows.length();n++)examRows.put(rows.getJSONObject(n));if(examPage<pages){web.evaluateJavascript("(function(){var next=document.getElementById('next_pager');if(!next||next.classList.contains('ui-state-disabled'))return false;window.__rainExamQuery.done=false;next.click();return true;})();",next->{if(!current(token))return;if(!"true".equals(next)){stop("考试分页未能完成，未保存结果，请重试。");return;}examPage++;deadline=System.currentTimeMillis()+60000;queue(500);});return;}SchoolExams.Result parsed=SchoolExams.parse(examRows);Agenda.prefs(this).edit().putLong("examQueryLast",System.currentTimeMillis()).putString("examQuerySummary","已公布时间："+parsed.events.length()+" 条 · 未公布或未识别："+parsed.unavailable+" 条").apply();if(parsed.events.length()==0){emptyExams(parsed.unavailable);return;}review(new Intent(this,ImportActivity.class).putExtra("examDraft",parsed.events.toString()).putExtra("examUnavailable",parsed.unavailable));}catch(Exception e){stop("考试结果格式暂不支持，未保存结果，请重试。");}});}
 void review(Intent intent){completed=true;autoEnabled=false;reading=false;generation++;handler.removeCallbacks(tick);CookieManager.getInstance().flush();startActivity(intent);finish();}
 void emptyExams(int unavailable){completed=true;autoEnabled=false;reading=false;generation++;handler.removeCallbacks(tick);LinearLayout root=Ui.screen(this,"学校考试");LinearLayout card=Ui.card(this,root);card.addView(Ui.text(this,unavailable>0?"考试时间尚未公布":"暂无考试安排",23));card.addView(Ui.hint(this,unavailable>0?"已自动查询。"+unavailable+" 条记录暂未公布时间或无法识别，公布后可重新查询。":"已完成本次查询，当前没有可添加的考试。"));card.addView(Ui.hint(this,"已有课表与考试提醒保持原样。"));Ui.primary(this,root,"完成",this::finish);Ui.link(this,root,"重新查询",this::recreate);}
 void restart(){generation++;handler.removeCallbacks(tick);web.stopLoading();autoEnabled=true;completed=false;reading=false;examOpened=false;portalRedirected=false;examPage=1;examRows=new JSONArray();anchor=null;deadline=0;showProgress("正在重新连接学校");web.loadUrl(PORTAL);}
 void stop(String message){generation++;autoEnabled=false;reading=false;handler.removeCallbacks(tick);pageProgress.setVisibility(View.GONE);progressBox.setVisibility(View.GONE);web.setVisibility(View.VISIBLE);actionBar.setVisibility(View.VISIBLE);read.setText("重试自动读取");hint.setText(message);}
 static boolean isSchoolLogin(String url){try{android.net.Uri u=android.net.Uri.parse(url);return "https".equals(u.getScheme())&&"cas-paas.hzau.edu.cn".equals(u.getHost())&&u.getPath()!=null&&u.getPath().startsWith("/cas/");}catch(Exception e){return false;}}
 void adaptLogin(WebView w,String url){if(!isSchoolLogin(url))return;try{if(mobileScript==null)mobileScript=asset("school-login-mobile.js");w.evaluateJavascript(mobileScript,null);}catch(Exception ignored){hint.setText("可双指缩放或滑动学校页面完成登录");}}
 static boolean allowed(String url){try{android.net.Uri u=android.net.Uri.parse(url);String h=u.getHost();return h!=null&&("https".equals(u.getScheme())&&(h.equals("hzau.edu.cn")||h.endsWith(".hzau.edu.cn"))||"http".equals(u.getScheme())&&h.equals("byjxyt.hzau.edu.cn"));}catch(Exception e){return false;}}
 void switchTab(String title){web.evaluateJavascript("(function(){var card=Array.from(document.querySelectorAll('.card-Common_Schedule,.card-Common_SemesterCourse')).find(function(node){return node.getClientRects().length&&getComputedStyle(node).visibility!=='hidden';});if(card){var tab=Array.from(card.querySelectorAll('.card-header li')).find(x=>x.textContent.trim()==="+JSONObject.quote(title)+");if(tab)tab.click();}})();",null);}
 protected void onPause(){if(web!=null)CookieManager.getInstance().flush();super.onPause();}
 @Override public void onBackPressed(){if(reading){stop("已暂停自动读取，可点重试重新开始。");return;}super.onBackPressed();}
 protected void onDestroy(){generation++;handler.removeCallbacks(tick);if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}